/* Shared controls for four independent original arcade games. */
(()=>{'use strict';const C=ArcadeCore,$=s=>document.querySelector(s),game=document.body.dataset.arcadeGame,meta=C.GAMES[game];
let storage;try{storage=localStorage;}catch{storage={getItem(){throw Error();},setItem(){throw Error();}};}const store=ArcadeStore.create(storage);
let state,selected=null,paused=true,keys=new Set(),last=0,dirty=false,aim={x:240,y:80},route=null,frame=0,lastScore=-1,lastStage=0,lastLives=0,shotVisual=null;
const colors=['#1675cb','#b74790','#138573','#a26613','#7050b8'],symbols=['●','▲','◆','■','✚'],tiles=['◇','✿','☀','☾','△','☆','♧','✚'];
const rules={
brick:['패들을 움직여 공을 튕기고 벽돌을 모두 없애세요. 3단계, 목숨 3개입니다.','PC: 화면을 클릭하지 않아도 ←/→ 또는 A/D로 이동합니다. Enter는 발사/계속, Space 또는 P는 시작/일시정지, Esc는 일시정지입니다. 마우스로 판 위를 움직여도 됩니다. 모바일은 판을 좌우로 끌거나 아래 이동 버튼을 사용하세요.','패들의 어느 부분에 맞히느냐에 따라 공의 반사각이 달라집니다. 같은 궤도가 반복되면 위치를 조금 바꿔보세요.','벽돌 하나 10점, 단계 완료 50점입니다. 공을 놓치면 목숨 하나를 잃고 다음 공을 직접 발사합니다.','설명·기록·다른 탭·페이지 이탈 시 일시정지합니다. 복구 후 계속 버튼을 눌러 재개합니다. 숨겨진 시간에 공이 움직이지 않습니다.'],
shisen:['같은 문양 두 개를 선택해 모두 지우세요. 6행 8열의 48장, 총 24쌍입니다.','상하좌우 직선으로 연결하며 직각으로 최대 두 번 꺾을 수 있습니다. 다른 타일을 통과할 수 없고 바깥 한 칸을 돌아갈 수 있습니다.','연결할 짝이 없어지면 남은 문양을 자동으로 재배치해 이어갑니다. 개수는 유지하고 재배치 횟수를 표시합니다.','짝당 100점, 힌트를 쓸 때마다 20점 차감합니다(최저 0점). 시간제한은 없습니다.','문양을 클릭하거나 키보드 화살표로 이동하고 Enter/Space로 선택합니다. 힌트는 연결 가능한 한 쌍을 표시합니다.'],
pop:['8×8 보드에서 상하좌우로 이어진 같은 색 블록 2개 이상을 고르세요. 대각선은 연결되지 않습니다.','선택한 그룹과 예상 점수를 확인한 뒤 제거를 누릅니다. 다른 블록을 눌러 선택을 바꿀 수 있습니다.','블록은 아래로 떨어지고 빈 열은 왼쪽으로 모입니다. 새 블록은 생기지 않습니다.','n개 제거 점수는 n×(n−1)×5점입니다. 모두 지우면 추가 500점, 제거 가능한 그룹이 없으면 현재 점수로 종료합니다.','색과 함께 모양을 표시합니다. 시간제한 없이 개인 최고점에 도전하세요.'],
bubble:['위쪽을 조준하고 발사하세요. 같은 색 버블이 3개 이상 이어지면 제거합니다. PC 마우스·터치로 조준하거나 화면 클릭 없이 ←/→ 또는 A/D로 조준하고 Space/Enter로 발사합니다. 누르고 있으면 방향이 계속 바뀝니다.','엇갈린 8열 보드입니다. 좌우 벽에 반사시킬 수 있으며 천장 또는 버블 옆의 빈칸에 붙습니다. 점선은 현재 발사의 경로입니다.','같은 색 연결 제거는 개당 10점, 그 뒤 천장과 연결이 끊겨 떨어지는 버블은 개당 20점입니다.','40발 안에 모두 지우면 성공입니다. 버블이 맨 아래 위험선에 닿거나 40발을 다 쓰거나 붙일 자리가 없으면 종료합니다.','현재 버블과 다음 버블을 보여줍니다. 진행·남은 발수·다음 버블은 새로고침에도 유지됩니다.']};
function warn(t){$('#save-warning').hidden=!t;$('#save-warning').textContent=t||'';}
function save(){const r=store.save(state);$('#save-status').textContent=r.ok?'진행·완료 기록을 이 브라우저에 저장했습니다.':'저장하지 못함 · 현재 페이지의 진행 유지';if(!r.ok)warn(r.error);dirty=!r.ok;return r;}
function best(){const rows=store.records().rows.filter(r=>r.game===game);return rows.length?Math.max(...rows.map(r=>r.score)):null;}
function newGame(){if(state&&!save().ok){warn('이전 결과·진행을 저장하지 못해 유지했습니다. 저장 공간을 확인해주세요.');return;}state=C.create(game,crypto.getRandomValues(new Uint32Array(1))[0]);selected=null;route=null;shotVisual=null;aim={x:240,y:80};paused=true;keys.clear();save();render();}
function requestNew(){pause();if(state.status==='playing')$('#solo-confirm').showModal();else newGame();}
function statusText(){const d=state.data;return game==='brick'?`${d.stage}/3단계 · 목숨 ${d.lives} · 남은 벽돌 ${d.bricks.filter(Boolean).length}`:game==='shisen'?`남은 ${d.board.filter(n=>n!==null).length/2}쌍 · 힌트 ${d.hints}회 · 자동 재배치 ${d.reshuffles}회`:game==='pop'?`남은 블록 ${64-d.removed}개 · 제거 ${d.groups}회`:`발사 ${d.shots}/40 · 남은 버블 ${d.board.filter(n=>n!==null).length}개`;}
function result(){if(state.status==='playing')return '';return `<section class="result-band ${state.status==='lost'?'failed':''}"><h2 id="phase-heading" tabindex="-1">${state.status==='won'?'모두 완성했어요!':state.status==='completed'?'더 지울 그룹이 없어요.':'이번 도전이 끝났어요.'}</h2><p class="result-value">${state.score}점</p><p>${statusText()}</p><div class="result-actions"><button class="primary" data-restart>새 도전</button><button data-records>내 기록</button><a class="button" href="index.html#games">게임 목록</a></div></section>`;}
function grid(){const d=state.data,shisen=game==='shisen',group=!shisen&&selected!==null?C.popGroup(d.board,selected):[],hint=shisen?d.hint:[];
if(shisen&&state.status==='won')return '<p class="selection-note">24쌍을 모두 연결했어요. 새 도전에서 다른 배치에 도전하세요.</p>';
const cells=d.board.map((n,i)=>`<button type="button" class="arcade-tile ${n===null?'empty':''} ${i===selected||group.includes(i)||hint.includes(i)?'chosen':''}" data-cell="${i}" style="--tile-color:${colors[(n||0)%5]}" aria-label="${Math.floor(i/8)+1}행 ${i%8+1}열 ${n===null?'빈칸':shisen?'문양 '+tiles[n]:'블록 '+symbols[n]}" aria-pressed="${i===selected||group.includes(i)||hint.includes(i)}" ${n===null||state.status!=='playing'?'disabled':''}>${n===null?'':shisen?tiles[n]:symbols[n]}</button>`).join('');
let board=`<div class="arcade-grid ${shisen?'shisen-grid':'pop-grid'}" role="group" aria-label="${shisen?'6행 8열 사천성':'8행 8열 블록 팝'}">${cells}</div>`;
if(shisen){const line=route?`<svg class="shisen-route" viewBox="0 0 10 8" aria-hidden="true"><polyline points="${route.map(([x,y])=>`${x+.5},${y+.5}`).join(' ')}"/></svg>`:'';board=`<div class="shisen-shell">${board}${line}</div>`;}
return board+(shisen?`<button type="button" data-hint ${state.status!=='playing'?'disabled':''}>힌트 보기 · −20점</button>`:`<p class="selection-note">${state.status!=='playing'?'남은 블록에는 지울 수 있는 그룹이 없습니다.':group.length>=2?`${group.length}개 선택 · +${group.length*(group.length-1)*5}점`:'같은 색 2개 이상이 이어진 그룹을 골라보세요.'}</p><button class="primary" data-remove ${state.status!=='playing'?'hidden':''} ${group.length<2?'disabled':''}>선택 블록 제거</button>`);}
function render(){const playing=state.status==='playing',top=best();$('#play').innerHTML=`${result()}${playing?'<h2 id="phase-heading" class="visually-hidden" tabindex="-1">게임 진행</h2>':''}<div class="play-status"><span id="arcade-phase">${statusText()}</span><span>점수 <strong id="arcade-score">${state.score}</strong></span></div><p class="dice-goal">${top===null?'첫 목표: 한 판을 마치고 첫 기록을 만드세요.':`저장된 개인 최고 ${top}점 · 새 도전으로 기록을 높여보세요.`}</p>${['shisen','pop'].includes(game)?grid():`${keyboardHelp()}<div class="arcade-canvas-wrap"><canvas id="arcade-canvas" width="480" height="560" tabindex="0" role="img" aria-label="${meta.name} 게임판. 조작 방법은 위 방법 보기와 아래 버튼을 사용하세요."></canvas></div>${game==='brick'?`<p id="brick-state" class="selection-note">${playing?'일시정지 · 발사 / 계속 버튼으로 시작하세요.':'도전 종료 · 새 도전을 선택하세요.'}</p><div class="arcade-controls"><button data-left ${playing?'':'disabled'} aria-label="패들 왼쪽">←</button><button class="primary" data-launch ${playing?'':'disabled'}>발사 / 계속</button><button data-pause ${playing?'':'disabled'}>일시정지</button><button data-right ${playing?'':'disabled'} aria-label="패들 오른쪽">→</button></div>`:`<p class="bubble-queue">현재 <strong style="color:${colors[state.data.current]}">${symbols[state.data.current]}</strong> · 다음 <strong style="color:${colors[state.data.next]}">${symbols[state.data.next]}</strong></p><div class="arcade-controls"><button data-aim="-1" ${playing?'':'disabled'} aria-label="왼쪽 조준">↖</button><button data-shoot class="primary" ${playing?'':'disabled'}>버블 발사</button><button data-aim="1" ${playing?'':'disabled'} aria-label="오른쪽 조준">↗</button></div><details><summary>버블판 문양으로 보기</summary><p class="bubble-readable">${Array.from({length:11},(_,r)=>state.data.board.slice(r*8,r*8+8).map(n=>n===null?'·':symbols[n]).join(' ')).join('<br>')}</p></details>`}`}`;
lastScore=state.score;lastStage=state.data.stage;lastLives=state.data.lives;draw();}
function act(a,quiet=false){const out=C.apply(state,a);if(out.error){$('#move-message').textContent=out.error;Sound.play('wrong');return false;}state=out.state;dirty=true;if(!quiet){save();render();if(state.status!=='playing')Sound.play(state.status==='lost'?'lose':'win');else Sound.play('select');}return true;}
function shoot(){
 if(shotVisual||state.status!=='playing')return;
 const board=state.data.board.slice(),color=state.data.current,route=C.traceBubble(board,aim).route;
 if(!act({type:'shoot',...aim}))return;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 shotVisual={board,color,route,start:performance.now()};document.querySelectorAll('[data-shoot],[data-aim]').forEach(b=>b.disabled=true);
 function animate(t){if(!shotVisual)return;if(t-shotVisual.start>=240||document.hidden){shotVisual=null;draw();document.querySelectorAll('[data-shoot],[data-aim]').forEach(b=>b.disabled=state.status!=='playing');return;}draw();requestAnimationFrame(animate);}requestAnimationFrame(animate);
}
function draw(){const canvas=$('#arcade-canvas');if(!canvas)return;const c=canvas.getContext('2d');c.clearRect(0,0,480,560);c.fillStyle='#102840';c.fillRect(0,0,480,560);
if(game==='brick'){const d=state.data;for(let i=0;i<d.bricks.length;i++)if(d.bricks[i]){const x=24+i%6*73,y=55+Math.floor(i/6)*29;c.fillStyle=colors[Math.floor(i/6)%5];c.fillRect(x,y,66,22);c.fillStyle='#ffffff60';c.fillRect(x+4,y+3,58,3);}c.fillStyle='#b9f3eb';c.fillRect(d.paddle-50,512,100,12);c.beginPath();c.arc(d.ball.x,d.ball.y,7,0,Math.PI*2);c.fillStyle='#fff4c3';c.fill();if(paused||d.serving){c.fillStyle='#ffffff';c.font='bold 20px sans-serif';c.textAlign='center';c.fillText(state.status==='playing'?'발사 / 계속을 누르세요':'도전 종료',240,300);}}
else{const d=state.data,board=shotVisual?shotVisual.board:d.board;for(let i=0;i<88;i++)if(board[i]!==null){const p=C.bubblePos(i);bubble(c,p.x,p.y,board[i]);}c.setLineDash([5,5]);c.strokeStyle='#ffd4b2';c.beginPath();c.moveTo(0,445);c.lineTo(480,445);c.stroke();c.setLineDash([]);if(state.status==='playing'&&!shotVisual){const trace=C.traceBubble(d.board,aim);c.strokeStyle='#dbeeff80';c.setLineDash([4,7]);c.beginPath();trace.route.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();c.setLineDash([]);}bubble(c,240,510,d.current);if(shotVisual){const v=shotVisual,progress=Math.min(1,(performance.now()-v.start)/240)*(v.route.length-1),i=Math.floor(progress),a=v.route[i],b=v.route[Math.min(i+1,v.route.length-1)],part=progress-i;bubble(c,a[0]+(b[0]-a[0])*part,a[1]+(b[1]-a[1])*part,v.color);}}
}
function bubble(c,x,y,n){c.beginPath();c.arc(x,y,20,0,Math.PI*2);c.fillStyle=colors[n];c.fill();c.lineWidth=2;c.strokeStyle='#ffffffaa';c.stroke();c.fillStyle='white';c.font='bold 20px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(symbols[n],x,y);}
function pause(){if(game==='brick'){paused=true;keys.clear();save();draw();if($('#brick-state'))$('#brick-state').textContent='일시정지 · 발사 / 계속을 눌러 재개하세요.';}}
function startBall(){if(state.status!=='playing')return;paused=false;if(state.data.serving)act({type:'launch'},true);save();draw();$('#brick-state').textContent='진행 중 · 패들의 위치로 반사각을 바꿔보세요.';}
function restoreAim(){const p=state?.view?.aim;aim=p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=480&&p.y>=0&&p.y<=470?{x:p.x,y:p.y}:{x:240,y:80};}
function rememberAim(p){aim=p;state.view={aim:{x:p.x,y:p.y}};dirty=true;draw();}
function turnAim(direction){const angle=Math.max(-1.25,Math.min(1.25,Math.atan2(aim.x-240,510-aim.y)+direction*.055)),t=Math.min(Math.abs(Math.sin(angle))<.001?10000:240/Math.abs(Math.sin(angle)),470/Math.cos(angle));rememberAim({x:Math.max(0,Math.min(480,240+Math.sin(angle)*t)),y:Math.max(0,Math.min(470,510-Math.cos(angle)*t))});}
function keyboardHelp(){return `<div class="keyboard-hint" aria-label="키보드 조작 안내">${game==='brick'?'<span><kbd>←</kbd><kbd>→</kbd> 또는 <kbd>A</kbd><kbd>D</kbd> 이동</span><span><kbd>Enter</kbd> 발사·계속</span><span><kbd>Space</kbd> / <kbd>P</kbd> 시작·멈춤</span>':'<span><kbd>←</kbd><kbd>→</kbd> 또는 <kbd>A</kbd><kbd>D</kbd> 조준</span><span><kbd>Space</kbd> / <kbd>Enter</kbd> 발사</span>'}<small>게임판을 먼저 클릭하지 않아도 조작할 수 있어요.</small></div>`;}
function point(e){const r=$('#arcade-canvas').getBoundingClientRect();return{x:Math.max(0,Math.min(480,(e.clientX-r.left)*480/r.width)),y:Math.max(0,Math.min(470,(e.clientY-r.top)*560/r.height))};}
$('#play').addEventListener('pointerdown',e=>{const target=e.target.closest('button');if(target?.hasAttribute('data-left'))keys.add('left');if(target?.hasAttribute('data-right'))keys.add('right');if(e.target.id==='arcade-canvas'){e.target.focus({preventScroll:true});const p=point(e);if(game==='brick'){e.target.setPointerCapture(e.pointerId);act({type:'move',x:p.x},true);save();draw();}else{rememberAim(p);}e.preventDefault();}});
$('#play').addEventListener('pointermove',e=>{if(e.target.id!=='arcade-canvas'||state.status!=='playing')return;const p=point(e);if(game==='brick'&&(e.pointerType==='mouse'||e.buttons)){act({type:'move',x:p.x},true);draw();}else if(game==='bubble'&&(e.pointerType==='mouse'||e.buttons)){rememberAim(p);}});
window.addEventListener('pointerup',()=>keys.clear());window.addEventListener('pointercancel',()=>keys.clear());
$('#play').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.hasAttribute('data-cell')){const i=Number(b.dataset.cell);if(game==='shisen'){if(selected===null||selected===i){selected=selected===i?null:i;route=null;render();}else{const a=selected;route=C.path(state.data.board,a,i);const reshuffles=state.data.reshuffles;if(act({type:'match',a,b:i})){selected=null;render();$('#move-message').textContent='연결 성공 · 다음 짝을 골라보세요.';if(state.data.reshuffles>reshuffles)$('#move-message').textContent='연결할 짝이 없어 남은 문양을 자동 재배치했습니다.';}else{selected=i;route=null;render();}}}else{selected=i;render();}}
 else if(b.hasAttribute('data-remove')){if(act({type:'remove',index:selected})){selected=null;render();}}
 else if(b.hasAttribute('data-hint')){selected=null;route=null;act({type:'hint'});}
 else if(b.hasAttribute('data-launch'))startBall();else if(b.hasAttribute('data-pause'))pause();
 else if(b.hasAttribute('data-shoot'))shoot();
 else if(b.hasAttribute('data-aim'))turnAim(Number(b.dataset.aim));
 else if(b.hasAttribute('data-restart'))requestNew();else if(b.hasAttribute('data-records'))openRecords();
});
document.addEventListener('keydown',e=>{
 if(['brick','bubble'].includes(game)){
  if(document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,[contenteditable="true"]'))return;
  const k=e.key.toLowerCase(),move=['arrowleft','arrowright','a','d'].includes(k),fire=[' ','enter'].includes(k),pauseKey=game==='brick'&&['p','escape'].includes(k);
  if(!move&&!fire&&!pauseKey)return;
  const control=e.target.closest('button,a,summary');if(control&&fire&&!control.matches('[data-launch],[data-shoot]'))return;
  if(state.status!=='playing')return;e.preventDefault();
  const canvas=$('#arcade-canvas'),r=canvas?.getBoundingClientRect();if(r&&(r.top<0||r.bottom>innerHeight))canvas.scrollIntoView({block:'center'});
  if(move){if(game==='brick')keys.add(['arrowleft','a'].includes(k)?'left':'right');else turnAim(['arrowleft','a'].includes(k)?-1:1);}
  else if(!e.repeat){if(game==='bubble')shoot();else if(k==='enter')startBall();else if(k==='escape')pause();else if(paused||state.data.serving)startBall();else pause();}
 }else{
  const b=e.target.closest('#play [data-cell]');if(!b)return;const dir={ArrowLeft:-1,ArrowRight:1,ArrowUp:-8,ArrowDown:8}[e.key];if(!dir)return;e.preventDefault();const i=Number(b.dataset.cell),n=i+dir;if(n>=0&&n<state.data.board.length&&(Math.abs(dir)===8||Math.floor(n/8)===Math.floor(i/8)))$(`[data-cell="${n}"]`)?.focus();
 }
});
window.addEventListener('keyup',e=>{if(['arrowleft','a'].includes(e.key.toLowerCase()))keys.delete('left');if(['arrowright','d'].includes(e.key.toLowerCase()))keys.delete('right');});
function loop(now){const dt=Math.min(.032,Math.max(.001,(now-last)/1000||.016));last=now;
 if(game==='brick'&&state.status==='playing'&&!document.hidden){if(keys.size)act({type:'move',x:Math.max(0,Math.min(480,state.data.paddle+(keys.has('right')?1:-1)*340*dt))},true);if(!paused){act({type:'step',dt},true);if(state.status!=='playing'){paused=true;save();render();Sound.play(state.status==='won'?'win':'lose');}else{if(state.data.serving&&$('#brick-state'))$('#brick-state').textContent='다음 공을 발사해주세요.';if(state.score!==lastScore||state.data.stage!==lastStage||state.data.lives!==lastLives){$('#arcade-score').textContent=state.score;$('#arcade-phase').textContent=statusText();lastScore=state.score;lastStage=state.data.stage;lastLives=state.data.lives;}draw();}}}frame=requestAnimationFrame(loop);}
function openRecords(){pause();const r=store.records();$('#records-warning').textContent=r.error;$('#record-list').innerHTML=Object.entries(C.GAMES).map(([id,g])=>{const rows=r.rows.filter(x=>x.game===id);return `<section class="record-summary"><h3>${g.name}</h3><p>${rows.length}회 완료 · 최고 ${rows.length?Math.max(...rows.map(x=>x.score))+'점':'기록 없음'}</p></section>`;}).join('')+r.rows.slice(0,20).map(r=>`<div class="suite-record"><b>${C.GAMES[r.game].name}</b> · ${r.score}점 · ${r.outcome==='won'?'성공':r.outcome==='lost'?'실패':'완료'}<small>${new Date(r.finishedAt).toLocaleString('ko-KR')}</small></div>`).join('');$('#solo-records').showModal();}
$('#open-rules').addEventListener('click',()=>{pause();$('#solo-rules').showModal();});$('#open-records').addEventListener('click',openRecords);$('#new-game').addEventListener('click',requestNew);$('#cancel-new').addEventListener('click',()=>$('#solo-confirm').close());$('#confirm-new').addEventListener('click',()=>{$('#solo-confirm').close();newGame();});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.close).close()));
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('blur',pause);window.addEventListener('pagehide',()=>{pause();save();});setInterval(()=>{if(dirty)save();},1000);
window.addEventListener('storage',e=>{if(e.key===store.sessionKey(game)){const read=store.load(game);if(read.state){state=read.state;restoreAim();paused=true;selected=null;render();$('#move-message').textContent='다른 탭의 진행을 반영했습니다.';}else warn(read.error);}});
document.title=meta.name+' | 판루딕';$('#game-title').textContent=meta.name;$('#game-tag').textContent='PANLUDIQ · ARCADE';$('#game-description').textContent={brick:'반사각을 바꾸고, 세 단계의 벽돌을 모두 깨세요.',shisen:'두 번 꺾기 안에 이어지는 같은 문양을 찾으세요.',pop:'크게 모아 지우고, 더 높은 점수에 도전하세요.',bubble:'벽을 활용해 조준하고, 같은 문양 세 개를 모으세요.'}[game];$('#rules-heading').textContent=meta.name+' · 방법 보기';$('#rules-list').innerHTML=rules[game].map(x=>`<li>${x}</li>`).join('');
const read=store.load(game);warn(read.error);if(read.state){state=read.state;restoreAim();save();render();$('#move-message').textContent='저장된 진행을 복구했습니다.';}else newGame();if(game==='brick')frame=requestAnimationFrame(loop);
})();
